def solve(orders):
    stats = {r["summary"]: r["total"] for r in orders.describe("total").head(5)}
    row = (orders.count(), orders.count(), stats["min"], stats["max"])
    return spark.createDataFrame([row], "orders BIGINT, priced BIGINT, lowest_total DECIMAL(10,2), highest_total DECIMAL(10,2)")
